      "fTerm": "ROOF COVERINGS; SKY-LIGHTS; GUTTERS; ROOF-WORKING TOOLS (coverings of outer walls by plaster or other porous material <b>E04F 13/00</b>)<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>In this subclass, the following expression is used with the meaning indicated:<ul type=\"\"disc\"\"><li>&quot;roof coverings&quot; includes any similar kind of watertight covering against rain, snow, hail, or the like, for other parts of buildings.</li></ul></li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ROOF COVERINGS</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Tiles or slates; slabs or stiff sheets; flexible materials</td><td><b>1/00</b>; <b>3/00</b>; <b>5/00</b>, <b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Bulk materials, straw or thatch</td><td><b>7/00</b>, <b>9/00</b>, <b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Other materials</td><td><b>11/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">SPECIAL ARRANGEMENTS IN CONNECTION WITH ROOF COVERINGS</td><td><b>12/00</b>, <b>13/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">APPARATUS OR TOOLS FOR ROOF WORKING</td><td><b>15/00</b></td></p></tr></table>",
